import { useEffect, useRef, useState } from 'react'
import { fmtTime } from '../api'
import { Modal, toast } from './ui'

export interface Share {
  url?: string
  problem?: string
  qrSize?: number
  qrRows?: string[]
  title: string
  endsAt?: number | null
  fileName: string
}

// The QR matrix is generated by our own server (go-qrcode) and drawn here on
// a local canvas; the tokenised link is never sent to any external service.
export function drawQR(canvas: HTMLCanvasElement, s: Share) {
  const rows = s.qrRows || []
  const n = rows.length
  const scale = Math.max(4, Math.floor(480 / Math.max(n, 1)))
  const qr = n * scale
  const pad = 24
  const w = qr + pad * 2
  const ctx = canvas.getContext('2d')!
  ctx.font = 'bold 20px system-ui, sans-serif'
  // wrap title to max 2 lines
  const words = (s.title || '').split(/\s+/)
  const lines: string[] = []
  let cur = ''
  for (const wd of words) {
    const t = cur ? cur + ' ' + wd : wd
    if (ctx.measureText(t).width > w - pad * 2 && cur) {
      lines.push(cur)
      cur = wd
    } else cur = t
  }
  if (cur) lines.push(cur)
  const titleLines = lines.slice(0, 2)
  const top = pad + titleLines.length * 26 + (titleLines.length ? 8 : 0)
  const h = top + qr + 64
  canvas.width = w
  canvas.height = h
  ctx.fillStyle = '#ffffff'
  ctx.fillRect(0, 0, w, h)
  ctx.fillStyle = '#000000'
  ctx.font = 'bold 20px system-ui, sans-serif'
  ctx.textBaseline = 'top'
  titleLines.forEach((l, i) => ctx.fillText(l, pad, pad + i * 26))
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) if (rows[y][x] === '1') ctx.fillRect(pad + x * scale, top + y * scale, scale, scale)
  ctx.font = '15px system-ui, sans-serif'
  ctx.fillText(s.endsAt ? `Amal qiladi: ${fmtTime(s.endsAt)} gacha (Toshkent vaqti)` : 'Muddat: havola sozlamasiga ko‘ra', pad, top + qr + 12)
  ctx.fillStyle = '#555'
  ctx.font = '13px system-ui, sans-serif'
  ctx.fillText('DronStream — maxsus havola. Begonalarga bermang.', pad, top + qr + 36)
}

function toBlob(c: HTMLCanvasElement): Promise<Blob> {
  return new Promise((res, rej) => c.toBlob((b) => (b ? res(b) : rej(new Error('PNG yaratilmadi'))), 'image/png'))
}

export default function ShareDialog({ share, onClose, heading }: { share: Share; onClose: () => void; heading?: string }) {
  const canvas = useRef<HTMLCanvasElement>(null)
  const [hint, setHint] = useState('')
  useEffect(() => {
    if (canvas.current && share.qrRows) drawQR(canvas.current, share)
  }, [share])

  const download = async () => {
    if (!canvas.current) return
    const blob = await toBlob(canvas.current)
    const a = document.createElement('a')
    a.href = URL.createObjectURL(blob)
    a.download = share.fileName // never contains the token
    a.click()
    setTimeout(() => URL.revokeObjectURL(a.href), 2000)
  }
  const copyLink = async () => {
    try {
      await navigator.clipboard.writeText(share.url!)
      toast('Havola nusxalandi', 'ok')
    } catch {
      setHint("Brauzer clipboard'ga yozishga ruxsat bermadi. Havolani maydondan belgilab, Ctrl+C bilan nusxalang.")
    }
  }
  const copyPNG = async () => {
    try {
      if (!canvas.current) throw new Error()
      if (typeof ClipboardItem === 'undefined' || !navigator.clipboard?.write) throw new Error('unsupported')
      const blob = await toBlob(canvas.current)
      await navigator.clipboard.write([new ClipboardItem({ 'image/png': blob })])
      toast('QR rasm nusxalandi', 'ok')
    } catch {
      setHint("Bu brauzer QR rasmni clipboard'ga nusxalashni qo'llamaydi. \"PNG yuklab olish\" tugmasidan foydalaning.")
    }
  }
  const systemShare = async () => {
    try {
      if (!navigator.share) throw new Error('unsupported')
      const blob = canvas.current ? await toBlob(canvas.current) : null
      const file = blob ? new File([blob], share.fileName, { type: 'image/png' }) : null
      if (file && navigator.canShare?.({ files: [file] })) {
        await navigator.share({ title: share.title, text: share.url, files: [file] })
      } else {
        await navigator.share({ title: share.title, url: share.url })
      }
    } catch (e: any) {
      if (e?.name === 'AbortError') return
      setHint("Bu qurilmada tizim ulashish oynasi mavjud emas. Havolani nusxalang yoki PNG ni yuklab oling.")
    }
  }

  return (
    <Modal title={heading || `Ulashish: ${share.title}`} onClose={onClose} wide>
      {share.problem ? (
        <div className="alert error">
          {share.problem} <a href="#/settings">Sozlamalarga o'tish</a>
        </div>
      ) : (
        <>
          <p className="small muted">
            Havola bir yoki bir necha kishiga beriladi. Kim olsa — o'sha foydalana oladi: oluvchi nomi tasdiqlangan shaxs emas. Havolani ommaviy joylarga qo'ymang.
          </p>
          <div className="copy-field">
            <input readOnly value={share.url} onFocus={(e) => e.currentTarget.select()} style={{ flex: '1 1 300px' }} aria-label="Havola" />
          </div>
          <div className="row gap wrap" style={{ margin: '8px 0' }}>
            <button className="primary" onClick={copyLink}>
              Havolani nusxalash
            </button>
            <button onClick={copyPNG}>QR rasmni nusxalash</button>
            <button onClick={download}>PNG yuklab olish</button>
            <button onClick={systemShare}>Ulashish…</button>
          </div>
          {hint && <div className="alert warn small">{hint}</div>}
          <canvas ref={canvas} className="qr-canvas" data-testid="qr-canvas" />
        </>
      )}
    </Modal>
  )
}
